-- English 2 final module. Run seed_english2_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'english-2';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Argumentative Essay (500 words or more)$j$, $j${"prompt": "Write an argumentative essay of at least 500 words on this question: Should every high school student be required to complete a course in personal finance before graduating? Take a clear position.\n\nYour essay must include: an introduction with a hook and a clear thesis; at least three body paragraphs, each with a reason supported by evidence and reasoning; a counterclaim with a rebuttal; transitions; and a conclusion. Use at least one quotation from Scripture (KJV) or from a text read in this course, and use ethos, pathos and logos on purpose. Avoid fallacies. Cite any outside source you use and give credit honestly. Revise and edit your draft before you submit it.", "rubric": "Total 100. Clear, debatable thesis: 10. Organization and transitions: 15. Evidence from at least two sources and reasoning: 25. Counterclaim and rebuttal: 15. Use of rhetorical appeals: 10. Style and word choice: 10. Conventions (grammar, spelling, punctuation): 15. Honest citation and no plagiarism: pass or fail requirement. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Argumentative Essay (500 words or more)$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: English 2$j$, $j${"questions": [{"q": "A theme is best stated as:", "options": ["A full statement of a message about life", "One word", "A list of characters", "The title of the text"]}, {"q": "Comparing two unlike things using the word like or as is a:", "options": ["Rhyme", "Simile", "Fragment", "Metaphor"]}, {"q": "'The LORD is my shepherd' is an example of a:", "options": ["Statistic", "Metaphor", "Simile", "Fallacy"]}, {"q": "Mood is:", "options": ["The setting only", "The feeling a text creates in the reader", "The author's age", "The number of lines"]}, {"q": "A good paraphrase:", "options": ["Leaves out credit", "Changes three words only", "Adds new facts", "Restates the idea in your own words and keeps the meaning"]}, {"q": "A text that explains why something happened and what followed uses:", "options": ["No structure", "Description only", "Cause and effect", "Chronological order only"]}, {"q": "Repeating a pattern of words or phrases for effect is:", "options": ["A footnote", "A comma splice", "Parallel structure", "A fragment"]}, {"q": "A central idea in a speech is:", "options": ["The speaker's title", "The date", "The first sentence only", "The most important point the speaker makes"]}, {"q": "An appeal to a speaker's credibility is:", "options": ["Irony", "Pathos", "Logos", "Ethos"]}, {"q": "An appeal that uses facts, numbers and clear reasoning is:", "options": ["Ethos", "Imagery", "Logos", "Pathos"]}, {"q": "'Do not trust her plan; she is new here' is an example of:", "options": ["A statistic", "Ad hominem", "A rebuttal", "Evidence"]}, {"q": "In an argument, a rebuttal:", "options": ["Describes the setting", "Answers the counterclaim", "Lists the sources", "States the title"]}, {"q": "Which task is editing?", "options": ["Choosing a new topic", "Fixing a comma splice", "Reorganizing the paragraphs", "Adding a new main idea"]}, {"q": "Using another person's words or ideas without credit is:", "options": ["Plagiarism", "A summary with credit", "A citation", "A paraphrase with credit"]}, {"q": "A letter written by a soldier during a war is a:", "options": ["Rumor", "Textbook", "Secondary source", "Primary source"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: English 2$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,1,3,2,2,3,3,2,1,1,1,0,3}'::int[], array[$j$A theme is a complete statement of the message.$j$,$j$A simile uses like or as.$j$,$j$It says the LORD is a shepherd without using like or as.$j$,$j$Mood is the atmosphere or feeling the reader gets.$j$,$j$A paraphrase uses your own words and keeps the meaning.$j$,$j$That is cause and effect.$j$,$j$Parallel structure repeats a pattern.$j$,$j$The central idea is the main point.$j$,$j$Ethos builds trust in the speaker.$j$,$j$Logos appeals to logic.$j$,$j$It attacks the person, not the plan.$j$,$j$The rebuttal responds to the opposing view.$j$,$j$Editing corrects errors in conventions.$j$,$j$That is plagiarism.$j$,$j$A letter from the time is a first hand record.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: English 2$j$ on conflict (item_id) do nothing;
end
$seed$;
